tasks.solution:
def total_price(items, delivery_fee):
    if delivery_fee < 0 or any(p < 0 or q < 0 for p, q in items):
        raise ValueError('Отрицательное значение')
    return sum(p * q for p, q in items) + delivery_fee if items else 0

