tasks.solution:
def take_shift(times, budget):
    used = 0
    count = 0
    for duration in times:
        if used + duration > budget:
            break
        used += duration
        count += 1
    return count

def unique_codes(codes):
    seen = set()
    result = []
    for code in codes:
        if code not in seen:
            result.append(code)
            seen.add(code)
    return result

