tasks.solution:
def delivered_summary(rows):
    groups = {}
    for row in rows:
        if row['status'] == 'done':
            groups.setdefault(row['zone'], []).append(row['minutes'])
    return {zone: sum(times) / len(times) for zone, times in groups.items()}
